ALTER TABLE sitios_bloqueados ADD COLUMN categoria VARCHAR(32) NOT NULL DEFAULT 'PERSONALIZADO';
ALTER TABLE sitios_bloqueados ADD COLUMN modo VARCHAR(16) NOT NULL DEFAULT 'BLOQUEAR';
ALTER TABLE sitios_bloqueados ADD COLUMN permanente BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE sitios_bloqueados ADD COLUMN vigente_desde TIMESTAMP(6) NULL;
ALTER TABLE sitios_bloqueados ADD COLUMN vigente_hasta TIMESTAMP(6) NULL;
ALTER TABLE sitios_bloqueados ADD COLUMN revision BIGINT NOT NULL DEFAULT 1;
ALTER TABLE sitios_bloqueados ADD CONSTRAINT ck_sitios_categoria CHECK (categoria IN ('ADULTOS','APUESTAS','REDES_SOCIALES','VIDEOJUEGOS','ENTRETENIMIENTO','PERSONALIZADO'));
ALTER TABLE sitios_bloqueados ADD CONSTRAINT ck_sitios_modo CHECK (modo IN ('BLOQUEAR','PERMITIR'));
ALTER TABLE sitios_bloqueados ADD CONSTRAINT ck_sitios_vigencia CHECK (vigente_hasta IS NULL OR vigente_desde IS NULL OR vigente_hasta > vigente_desde);
CREATE TABLE sitios_dispositivos (sitio_id BIGINT NOT NULL, dispositivo_id BIGINT NOT NULL, familia_id BIGINT NOT NULL, sincronizado_en TIMESTAMP(6) NULL, CONSTRAINT pk_sitios_dispositivos PRIMARY KEY (sitio_id,dispositivo_id), CONSTRAINT fk_sd_sitio FOREIGN KEY(sitio_id) REFERENCES sitios_bloqueados(id) ON DELETE RESTRICT, CONSTRAINT fk_sd_dispositivo FOREIGN KEY(familia_id,dispositivo_id) REFERENCES dispositivos(familia_id,id) ON DELETE RESTRICT);
CREATE INDEX ix_sd_dispositivo ON sitios_dispositivos(familia_id,dispositivo_id);
CREATE TABLE horarios_sitios (id BIGINT NOT NULL AUTO_INCREMENT,sitio_id BIGINT NOT NULL,dia_semana VARCHAR(12) NOT NULL,hora_inicio TIME NOT NULL,hora_fin TIME NOT NULL,cruza_medianoche BOOLEAN NOT NULL DEFAULT FALSE,tipo_regla VARCHAR(16) NOT NULL DEFAULT 'BLOQUEAR',activo BOOLEAN NOT NULL DEFAULT TRUE,creado_en TIMESTAMP(6) NOT NULL,actualizado_en TIMESTAMP(6) NOT NULL,CONSTRAINT pk_horarios_sitios PRIMARY KEY(id),CONSTRAINT uq_horarios_sitios UNIQUE(sitio_id,dia_semana,hora_inicio,hora_fin,tipo_regla),CONSTRAINT fk_hs_sitio FOREIGN KEY(sitio_id) REFERENCES sitios_bloqueados(id) ON DELETE RESTRICT,CONSTRAINT ck_hs_dia CHECK(dia_semana IN ('MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY','SUNDAY')),CONSTRAINT ck_hs_tipo CHECK(tipo_regla IN ('BLOQUEAR','PERMITIR')),CONSTRAINT ck_hs_intervalo CHECK(hora_inicio <> hora_fin));
CREATE TABLE categorias_sitios (id BIGINT NOT NULL AUTO_INCREMENT,clave VARCHAR(32) NOT NULL,nombre VARCHAR(80) NOT NULL,fuente_url VARCHAR(500) NULL,version_datos VARCHAR(80) NULL,actualizado_en_fuente TIMESTAMP(6) NULL,disponible BOOLEAN NOT NULL DEFAULT FALSE,activo BOOLEAN NOT NULL DEFAULT TRUE,creado_en TIMESTAMP(6) NOT NULL,actualizado_en TIMESTAMP(6) NOT NULL,CONSTRAINT pk_categorias_sitios PRIMARY KEY(id),CONSTRAINT uq_categorias_clave UNIQUE(clave));
INSERT INTO categorias_sitios(clave,nombre,disponible,activo,creado_en,actualizado_en) VALUES ('ADULTOS','Contenido para adultos',FALSE,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),('APUESTAS','Apuestas',FALSE,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),('REDES_SOCIALES','Redes sociales',FALSE,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),('VIDEOJUEGOS','Videojuegos',FALSE,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),('ENTRETENIMIENTO','Entretenimiento',FALSE,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),('PERSONALIZADO','Sitios personalizados',TRUE,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
CREATE TABLE dominios_categoria (id BIGINT NOT NULL AUTO_INCREMENT,categoria_id BIGINT NOT NULL,dominio VARCHAR(253) NOT NULL,fuente VARCHAR(500) NOT NULL,verificado_en TIMESTAMP(6) NOT NULL,activo BOOLEAN NOT NULL DEFAULT TRUE,creado_en TIMESTAMP(6) NOT NULL,actualizado_en TIMESTAMP(6) NOT NULL,CONSTRAINT pk_dominios_categoria PRIMARY KEY(id),CONSTRAINT uq_dominio_categoria UNIQUE(categoria_id,dominio),CONSTRAINT fk_dc_categoria FOREIGN KEY(categoria_id) REFERENCES categorias_sitios(id) ON DELETE RESTRICT);
CREATE TABLE eventos_sitios (id BIGINT NOT NULL AUTO_INCREMENT,familia_id BIGINT NOT NULL,sitio_id BIGINT NOT NULL,dispositivo_id BIGINT NOT NULL,evento_uuid VARCHAR(36) NOT NULL,dominio VARCHAR(253) NOT NULL,tipo VARCHAR(32) NOT NULL,detalle VARCHAR(500) NULL,ocurrido_en TIMESTAMP(6) NOT NULL,exitoso BOOLEAN NOT NULL,activo BOOLEAN NOT NULL DEFAULT TRUE,creado_en TIMESTAMP(6) NOT NULL,actualizado_en TIMESTAMP(6) NOT NULL,CONSTRAINT pk_eventos_sitios PRIMARY KEY(id),CONSTRAINT uq_eventos_sitios_uuid UNIQUE(evento_uuid),CONSTRAINT fk_es_sitio FOREIGN KEY(sitio_id) REFERENCES sitios_bloqueados(id) ON DELETE RESTRICT,CONSTRAINT fk_es_dispositivo FOREIGN KEY(familia_id,dispositivo_id) REFERENCES dispositivos(familia_id,id) ON DELETE RESTRICT);
CREATE INDEX ix_eventos_sitios_consulta ON eventos_sitios(familia_id,dispositivo_id,ocurrido_en);
